"""Build a local, network-free listening/review index from final Korean masters."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];A=R/'authoring/voices020';D=R/'docs/voices020'
def main():
 manifest=json.loads((A/'VOICE_SCRIPTS.json').read_text(encoding='utf-8'));generated={json.loads(l)['id']:json.loads(l) for l in (A/'ENCODED_BANK.jsonl').read_text(encoding='utf-8').splitlines()};rows=[]
 for r in manifest['records']:
  x=generated[r['id']];rows.append({k:r[k] for k in ('id','profile','age','context','line','take','meaning','historical_target','synthesis_text','linguistic_status','phonetic_respellings')}|{'audio':'../../inputs/native/'+x['member'],'seconds':x['quality']['seconds']})
 payload=json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('</','<\/')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Korean voices 0.2.0 listening review</title><style>
 :root{font-family:system-ui,sans-serif;color:#172334;background:#f3f5f7}body{max-width:1050px;margin:32px auto;padding:0 20px}h1{font-size:28px;margin-bottom:8px}p{line-height:1.55}.notice{background:#fff1cd;border-left:4px solid #b67b00;padding:14px 18px}.filters{display:flex;gap:14px;flex-wrap:wrap;position:sticky;top:0;background:#f3f5f7;padding:16px 0;border-bottom:1px solid #ccd4de}label{display:grid;gap:5px;font-weight:600;font-size:13px}select{padding:9px;min-width:160px;border:1px solid #bbc5d0;border-radius:6px}article{background:white;border:1px solid #d8dee7;border-radius:10px;margin:14px 0;padding:18px}h2{font-size:15px;margin:0 0 10px}.ko{font-size:22px;line-height:1.6;margin:8px 0}.muted{color:#526176;font-size:13px}audio{width:min(100%,430px);margin-top:10px}details{font-size:13px;margin-top:8px}code{word-break:break-all;font-size:11px}</style>
 <h1>Korean unit voices · 0.2.0</h1><p>Original fictional voices and composed game dialogue. Compare ages, lines and independent takes. Audio stays on this computer.</p>
 <p class="notice"><strong>Historical and native-speaker review is pending.</strong> Earlier-age forms are uncertain retrojections; modern synthesis has not recovered Old/Middle Korean phonology. Technical decode/language checks are separate from pronunciation or audible in-game acceptance.</p>
 <div class="filters"><label>Unit voice<select id="role"></select></label><label>Age<select id="age"><option value="1">I · Silla projection</option><option value="2">II · Goryeo projection</option><option value="3">III · Editorial transition</option><option value="4">IV · Joseon-inspired</option></select></label><label>Response<select id="event"></select></label></div>
 <p id="count" class="muted"></p><main id="clips"></main><p class="muted">Repair recordings are retained for review; the current game dispatcher uses neutral acknowledgements for unqualified repair/religious targets. Some early banks are authoring extras for units only available later. Gameplay production ages remain unchanged.</p>
 <script id="data" type="application/json">PAYLOAD</script><script>
 const rows=JSON.parse(document.getElementById('data').textContent),role=document.getElementById('role'),age=document.getElementById('age'),event=document.getElementById('event'),main=document.getElementById('clips');
 function option(text,value){const o=document.createElement('option');o.textContent=text;o.value=value;return o}
 [...new Set(rows.map(x=>x.profile))].sort().forEach(x=>role.append(option(x.replaceAll('_',' '),x)));
 function contexts(){const previous=event.value;event.replaceChildren();[...new Set(rows.filter(x=>x.profile===role.value).map(x=>x.context))].forEach(x=>event.append(option(x.replaceAll('_',' '),x)));if([...event.options].some(x=>x.value===previous))event.value=previous;render()}
 function text(tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e}
 function render(){main.querySelectorAll('audio').forEach(a=>a.pause());main.replaceChildren();const selected=rows.filter(x=>x.profile===role.value&&x.age===Number(age.value)&&x.context===event.value).sort((a,b)=>a.line-b.line||a.take-b.take);document.getElementById('count').textContent=selected.length+' recordings · six alternative lines; takes are independently synthesized';for(const r of selected){const a=document.createElement('article');a.append(text('h2','Line '+r.line+' · Take '+r.take+' · '+r.seconds.toFixed(2)+' s'),text('p',r.historical_target,'ko'),text('p',r.meaning),text('p','Synthesis input: '+r.synthesis_text,'muted'));const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=r.audio;audio.addEventListener('play',()=>document.querySelectorAll('audio').forEach(x=>{if(x!==audio)x.pause()}));a.append(audio);const details=document.createElement('details');details.append(text('summary','Confidence and reconstruction limits'),text('p',r.linguistic_status.text_confidence+' — '+r.linguistic_status.limit),text('code',r.id));a.append(details);main.append(a)}}
 role.addEventListener('change',contexts);age.addEventListener('change',render);event.addEventListener('change',render);contexts();
 </script></html>'''.replace('PAYLOAD',payload)
 target=D/'VOICE_REVIEW.html';target.write_text(page,encoding='utf-8');print('LOCAL_VOICE_REVIEW',len(rows),'CLIPS',target)
if __name__=='__main__':main()
